    [752] = { name = "Руна долі могу", en = "Mogu Rune of Fate", desc = "Володіння Руною долі могу дає щасливому власнику змогу ризикнути руною, щоб отримати додаткову винагороду в Тронній Залі Грому, від Налака чи Оондасти.", den = "Possession of the Mogu Rune of Fate allows its lucky owner to risk a rune to receive a bonus reward from the Throne of Thunder, Nalak or Oondasta." },
