    [776] = { name = "Бойова печатка", en = "Warforged Seal", desc = "Володіння Бойовою печаткою дає щасливому власнику змогу ризикнути печаткою, щоб отримати додаткову винагороду в Облозі Оґриммару, Випробуваннях Небожителів і від Ордоса.", den = "Possession of the Warforged Seal allows its lucky owner to risk a seal to receive a bonus reward from the Siege of Orgrimmar, the Celestial Trials, and Ordos." },
    [777] = { name = "Позачасова монета", en = "Timeless Coin", desc = "Ви відчуваєте, як примарні пальці минулих і прийдешніх власників цієї монети ковзають вашою долонею, наче сам час розмивається. Витрачайте її на Позачасовому Острові, щоб здобути потужні й мінливі винагороди.", den = "You feel the shadowy fingers of previous and future owners of this coin playing across your hand, as if time itself blurs. Spend upon the Timeless Isle to earn powerful and fluid rewards." },
