    [1149] = { name = "Незряче око", en = "Sightless Eye", desc = "Груба монета, викарбувана вручну. На ній зображено символ, схожий на знак Кірін-Тор, з однією важливою відмінністю: око заплющене.", den = "A rough, hand-minted coin. It bears a symbol similar to that of the Kirin Tor, with one key difference: the eye is closed." },
