    [1268] = { name = "Древній артефакт", en = "Timeworn Artifact", desc = "Загадковий артефакт наг із глибин Великого моря. Король Мргл-Мргл шукає такі на Древньому узбережжі.", den = "A mysterious naga artifact from the depths of the Great Sea. King Mrgl-Mrgl is looking for these at Timeworn Strand." },
    [1273] = { name = "Печатка зламаної долі", en = "Seal of Broken Fate", desc = "Викривлює долю, даючи нагоду здобути додаткові скарби з босів рейдів і міфічних підземель Legion.", den = "Twists fate to provide an opportunity for additional treasure from Legion raid and Mythic dungeon bosses." },
    [1275] = { name = "Дивовижна монета", en = "Curious Coin", desc = "Ця незвична монета тепла на дотик і легенько вібрує у вашій руці. Використовується, щоб придбати речі в Зур'іоса в Даларані.", den = "This unusual coin is warm to the touch and vibrates gently in your hand. Used to procure items from Xur'ios in Dalaran." },
