    [1314] = { name = "Уламок задушеної душі", en = "Lingering Soul Fragment", desc = "Уламок душі, що колись належала могутньому ворогові.", den = "Soul fragment once belonging to a powerful enemy." },
    [1324] = { name = "Кіраджійська відзнака Орди", en = "Horde Qiraji Commendation", desc = "Виконання цього завдання надасть Орді залік у події «Поклик скарабея».\n\nФракція, яка заробить найбільше заліку сьогодні, зможе вивісити свої прапори біля Гонга скарабея до кінця року.", den = "Completing this quest will grant the Horde credit in the Call of the Scarab event.\n\nThe faction which earns the most credit today may hang their banners by the Scarab Gong for the rest of the year." },
    [1325] = { name = "Кіраджійська відзнака Альянсу", en = "Alliance Qiraji Commendation", desc = "Виконання цього завдання надасть Альянсу залік у події «Поклик скарабея».\n\nФракція, яка заробить найбільше заліку сьогодні, зможе вивісити свої прапори біля Гонга скарабея до кінця року.", den = "Completing this quest will grant the Alliance credit in the Call of the Scarab event.\n\nThe faction which earns the most credit today may hang their banners by the Scarab Gong for the rest of the year." },
    [1342] = { name = "Воєнні припаси Падіння Легіону", en = "Legionfall War Supplies", desc = "Використовуються для подальшого спорудження цінних будівель на Зламаному березі.", den = "Used to further the construction of valuable structures on the Broken Shore." },
    [1347] = { name = "Споруда Падіння Легіону — Особистий лічильник — Вежа магів (прихована)", en = "Legionfall Building - Personal Tracker - Mage Tower (Hidden)" },
