    [1350] = { name = "Споруда Падіння Легіону — Особистий лічильник — Нижньосвітна вежа (прихована)", en = "Legionfall Building - Personal Tracker - Nether Tower (Hidden)" },
    [1355] = { name = "Сутність Скверни", en = "Felessence", desc = "Сконцентрована демонічна сутність, яку можна зібрати та використати, щоб створити обладунки великої сили.", den = "Concentrated demonic essence which can be captured and used to create armor of great power." },
    [1356] = { name = "Відлуння битви", en = "Echoes of Battle", desc = "Використовується, щоб купувати потужні PvP-обладунки. Наприкінці сезону ця валюта перетворюється на золото.", den = "Used to purchase powerful PvP armor. At the end of the season, this currency converts to gold." },
    [1357] = { name = "Відлуння панування", en = "Echoes of Domination", desc = "Використовується, щоб купувати елітні PvP-обладунки. Наприкінці сезону ця валюта перетворюється на золото.", den = "Used to purchase elite PvP armor. At the end of the season, this currency converts to gold." },
    [1379] = { name = "Жетон Випробування стилю", en = "Trial of Style Token", desc = "Заробляється участю у Випробуванні стилю. Можна обміняти на спорядження для трансмогрифікації в більшості великих міст.", den = "Earned by participating in the Trial of Style. Can be exchanged for transmoggable gear in most major cities." },
    [1388] = { name = "Уламки обладунків", en = "Armor Scraps", desc = "Збираються з ворожих військ і техніки по всьому воєнному фронту. Використовуються для навчання військ і просування досліджень.", den = "Gathered from enemy troops and vehicles throughout the warfront. Used in the training of troops and advancing research." },
    [1401] = { name = "Припаси твердині", en = "Stronghold Supplies", desc = "Використовуються, щоб зводити будівлі та виконувати дослідницькі покращення на воєнному фронті.", den = "Used to build structures and perform research upgrades within a Warfront." },
    [1416] = { name = "Монети повітря", en = "Coins of Air", desc = "За деякий час випаровуються в туман.", den = "Evaporate into mist after a while." },
    [1501] = { name = "Звивна сутність", en = "Writhing Essence", desc = "Використовується, щоб покращувати легендарні речі Legion до рівня предмета 970.", den = "Used to upgrade Legion Legendary items to item level 970." },
    [1506] = { name = "Дороговказний камінь Аргуса", en = "Argus Waystone", desc = "Використовується слугами Саргераса, щоб силоміць відкривати портали з Аргуса до інших світів під контролем Легіону.", den = "Used by the minions of Sargeras to force open portals from Argus to other Legion-controlled worlds." },
    [1508] = { name = "Завуальований аргуніт", en = "Veiled Argunite", desc = "Цей тьмяний кристал високо цінують ефірні торговці, особливо тауматург Вашрін на борту «Віндікаара».", den = "This dull-colored crystal is highly valued by ethereal traders, especially Thaumaturge Vashreen aboard the Vindicaar." },
    [1533] = { name = "Сутність пробудження", en = "Wakening Essence", desc = "Використовується арканомантом Врідіелем у Даларані над Зламаними островами, щоб створювати або покращувати легендарні речі Legion.", den = "Used by Arcanomancer Vridiel in Dalaran above the Broken Isles to create or upgrade Legion Legendary items." },
    [1534] = { name = "Археологічний фрагмент: зандалари", en = "Zandalari Archaeology Fragment" },
    [1535] = { name = "Археологічний фрагмент: друсти", en = "Drust Archaeology Fragment" },
    [1540] = { name = "Деревина", en = "Wood", desc = "Збирається рубанням дерев і з куп деревини по всьому воєнному фронту. Використовується, щоб зводити будівлі та покращувати війська.", den = "Gathered by harvesting trees and piles of wood throughout the warfront. Used to construct buildings and upgrade troops." },
    [1541] = { name = "Залізо", en = "Iron", desc = "Збирається по всьому воєнному фронту. Використовується, щоб зводити будівлі та збільшувати силу вашу й ваших союзників.", den = "Gathered throughout the warfront. Used to construct buildings and increase the power of you and your allies." },
    [1553] = { name = "Азерит", en = "Azerite", desc = "Кров Азерота кристалізується в брили азериту — надзвичайно потужного й могутнього матеріалу.", den = "The blood of Azeroth crystalizes into chunks of Azerite, an extremely potent and powerful material." },
    [1559] = { name = "Сутність бур", en = "Essence of Storms", desc = "Надзвичайно рідкісна, знаходиться під час убивства ворогів на воєнному фронті. Використовується, щоб надати собі нестримну силу біля Вівтаря.", den = "Extremely rare, found while killing enemies in the warfront. Used to grant yourself unbridled power at the Altar." },
    [1560] = { name = "Воєнні ресурси", en = "War Resources", desc = "Використовуються, щоб набирати війська, виконувати місії та досліджувати покращення для вашого воєнного зусилля.", den = "Used to recruit troops, run missions, and research upgrades for your war effort." },
    [1565] = { name = "Уламок багатого азериту", en = "Rich Azerite Fragment", desc = "Уламок багатого азериту. Здайте найближчому Воєнному майстрові заради нагород.", den = "A fragment of rich Azerite. Turn-in to a nearby War Master for rewards." },
    [1579] = { name = "Захисники Азерота", en = "Champions of Azeroth", desc = "Надає репутацію із Захисниками Азерота.", den = "Grants reputation with the Champions of Azeroth." },
    [1580] = { name = "Печатка пошарпаної долі", en = "Seal of Wartorn Fate", desc = "Викривлює долю, даючи нагоду здобути додаткові скарби з босів рейдів і підземель Battle for Azeroth.", den = "Twists fate to provide an opportunity for additional treasure from Battle for Azeroth raid and dungeon bosses." },
    [1585] = { name = "Честь усього загону", en = "Warband Wide Honor", desc = "Надається за вбивство ворогів вашої фракції.", den = "Granted from slaying enemies of your faction" },
    [1586] = { name = "Рівень честі", en = "Honor Level", desc = "Надається за вбивство багатьох ворогів вашої фракції.", den = "Granted from slaying many enemies of your faction" },
    [1587] = { name = "Воєнні припаси", en = "War Supplies", desc = "Використовуються, щоб зібрати військо для Битви за Стромґард.", den = "Used to raise a force for the Battle of Stromgarde" },
