    [1602] = { name = "Звитяга", en = "Conquest", desc = "Заробляється в рейтингових PvP-активностях. Використовується, щоб купувати рейтингове PvP-спорядження.", den = "Earned from Rated PvP activities. Used to purchase Rated PvP equipment." },
