    [1710] = { name = "Дублон мореплавця", en = "Seafarer's Dubloon", desc = "Валюта, якою користуються численні різноманітні племена Великого моря. Слугує для придбання речей у торговців під час острівних експедицій.", den = "Currency used by the many varied tribes of the Great Sea. Used to procure items from traders on Island Expeditions." },
    [1714] = { name = "Бойові фронти — Особистий лічильник — Деревина у скрині (прихований)", en = "Warfronts - Personal Tracker - Wood in Chest (Hidden)" },
    [1715] = { name = "Скалка прародителя", en = "Progenitor Shard", desc = "TEST", den = "TEST" },
    [1716] = { name = "Медаль за службу Присяжних честі", en = "Honorbound Service Medal", desc = "Відзнака за заслуги у битвах на полях Кул-Тіраса, Зандалара та на діючих фронтах війни. Її прагне постачальниця Мукра в порту Зандалара. За Орду!", den = "A badge of merit for action taken on the battlefields of Kul Tiras, Zandalar, and active Warfronts. Sought by Provisioner Mukra at the port of Zandalar. For the Horde!" },
    [1717] = { name = "Медаль за службу 7-го легіону", en = "7th Legion Service Medal", desc = "Відзнака за заслуги у битвах на полях Кул-Тіраса, Зандалара та на діючих фронтах війни. Її прагне постачальник Стійкий Горн у Бораласі. За Альянс!", den = "A badge of merit for action taken on the battlefields of Kul Tiras, Zandalar, and active Warfronts. Sought by Provisioner Stoutforge in Boralus. For the Alliance!" },
    [1718] = { name = "Залишок титанів", en = "Titan Residuum", desc = "Знесилені рештки азеритового обладунку, яких прагнуть ефірні торговці в Бораласі та Зандаларі. Здобувається з щотижневих скринь міфічних ключових каменів, а також через розбирання чи розчаклування азеритового обладунку.", den = "Unpowered remnants of Azerite armor coveted by ethereal traders in Boralus and Zandalar. Obtained from Mythic Keystone weekly chests and by scrapping or disenchanting Azerite armor." },
    [1719] = { name = "Зіпсовані спогади", en = "Corrupted Mementos", desc = "Уламки пам'яті з жахливих видінь Н'Зота, які можна дослідити в Титанічному дослідницькому архіві в Палаті серця.", den = "Fragments of memory from Horrific Visions of N'Zoth which can be analyzed at the Titanic Research Archive in the Chamber of Heart." },
    [1721] = { name = "Призматична манова перлина", en = "Prismatic Manapearl", desc = "Мерехтлива сфера прихованої енергії, яку можна знайти довкола Назжатара. Її можна обміняти на рідкісні й могутні речі або використати для підсилення бентичного обладунку.", den = "A glistening sphere of arcane energy found around Nazjatar. These can be traded for rare and powerful items, or used to empower Benthic armor." },
    [1722] = { name = "Азеритова руда", en = "Azerite Ore", desc = "Збирається по всьому острову. Використовується для будівництва споруд застави.", den = "Gathered across the Island. Used to construct outpost buildings." },
    [1723] = { name = "Деревина", en = "Lumber", desc = "Збирається по всьому острову. Використовується для будівництва споруд застави.", den = "Gathered across the Island. Used to construct outpost buildings." },
    [1728] = { name = "Фантазма", en = "Phantasma", desc = "Це згасле пасмо аніми можна використати, щоб здобути силу в Торгасті.\n\nПісля виходу з Торгаста вся фантазма знищується.", den = "This extinguished strand of anima can be used to gain power within Torghast.\n\nLeaving Torghast will destroy all Phantasma." },
    [1738] = { name = "Звільнені", en = "Unshackled", desc = "Надає репутацію зі Звільненими.", den = "Grants reputation with the Unshackled." },
