    [1752] = { name = "Вулик Медоспинів", en = "Honeyback Hive", desc = "Надає репутацію з Вуликом Медоспинів.", den = "Grants reputation with the Honeyback Hive." },
    [1754] = { name = "Відзнака Срібного авангарду", en = "Argent Commendation", desc = "Відзнака від Срібного хрестового походу на півночі Крижаної корони за дії проти військ-загарбників із Темних земель.", den = "Commendation from the Argent Crusade in northern Icecrown for actions taken against the invading forces of the Shadowlands." },
    [1755] = { name = "Об'єднані видіння", en = "Coalescing Visions", desc = "Вратіон може перетворити ці видіння на посудину, що дасть тобі доступ до жахливого видіння Н'Зота.", den = "Wrathion can manipulate these visions into a vessel that will allow you to gain access to a Horrific Vision of N'Zoth." },
