    [1802] = { name = "Поступ щотижневих нагород PvP Shadowlands", en = "Shadowlands PvP Weekly Reward Progress", desc = "Накопичуй цю валюту, щоб отримати нагороди зі щотижневої скрині в Орибосі.", den = "Acquire this currency to attain rewards from the weekly chest in Oribos." },
    [1803] = { name = "Відлуння Ні'алоти", en = "Echoes of Ny'alotha", desc = "Очищену від зіпсуття Н'Зота, цю речовину МАТИ може використати для синтезу сутностей у Палаті серця.", den = "Scoured of N'Zoth's corruption, MOTHER can use this substance to synthesize essences in the Chamber of Heart." },
