    [1810] = { name = "Спокутувана душа", en = "Redeemed Soul", desc = "Виняткова душа, що бажає долучитися до підсилення твого святилища ковенанту.", den = "An exceptional soul that wishes to contribute to empowering your Covenant Sanctum." },
