    [1977] = { name = "Стигійський жар", en = "Stygian Ember", desc = "Колись хоробрий воїн, нині — лиш дещиця нежиті.\n\nКісткова ковалиха Гайрмір у Кортії може використати їх, щоб покращити Скалки панування.", den = "Once a brave warrior, now reduced to a sliver of undeath.\n\nBonesmith Heirmir in Korthia can use these to improve Shards of Domination." },
    [1979] = { name = "Шифри Перших", en = "Cyphers of the First Ones", desc = "|L290-Відлуння сили, якою викували саму реальність. Можна розшифрувати на Шифрувальній консолі Фіріма в Закутку Вигнанця.|l", den = "|L290-Echoes of the power used to forge reality itself. Can be deciphered at Firim's Cypher Console in Exile's Hollow.|l" },
