    [2002] = { name = "Визнання — Кентаври Маруук", en = "Renown-Maruuk Centaur", desc = "Це визнання", den = "It's Renown" },
    [2003] = { name = "Припаси Драконових островів", en = "Dragon Isles Supplies", desc = "Різноманітні ресурси та будівельні матеріали, що можуть допомогти дружнім фракціям Драконових островів у боротьбі проти первісників. Використовуються для придбання предметів, відкритих за визнання.", den = "Various resources and building materials that can assist the friendly factions of the Dragon Isles in their fight against the Primalists. Used to purchase items unlocked from renown." },
    [2005] = { name = "Очки талантів друїда (DNT)", en = "Druid Talent Points (DNT)" },
    [2006] = { name = "Очки талантів відновлення (DNT)", en = "Restoration Talent Points (DNT)" },
    [2009] = { name = "Космічний потік", en = "Cosmic Flux", desc = "Вируючі уламки енергії творення, що уможливлюють перетворення. Космічний потік можна використати, щоб підсилити спорядження в Каталізаторі творення в Зерет-Мортісі або наснажити Палату Карбувальника рун у Торгасті.", den = "Swirling fragments of creation energy that enable transformation, Cosmic Flux can be used to empower equipment at the Creation Catalyst in Zereth Mortis or fuel the Runecarver's Chamber in Torghast." },
    [2011] = { name = "Оздоби подоби", en = "Effigy Adornments", desc = "Виготовлені шикаарами, ці оздоби можуть покращувати подоби Великого полювання.", den = "Crafted by the Shikaar, these adornments can enhance Major Hunt effigies." },
