    [2023] = { name = "Ковальські знання Драконових островів", en = "Dragon Isles Blacksmithing Knowledge", desc = "Використовуйте знання, щоб опанувати спеціалізації ковальства.\n\nЗнання можна здобути різними способами: наприклад, уперше виготовивши рецепт або виконавши завдання, доступні на Ринку ремісників у Валдраккені.", den = "Use Knowledge to learn Blacksmithing Specializations.\n\nKnowledge can be gained through various means such as crafting recipes for the first time and completing quests offered in the Artisan's Market in Valdrakken." },
    [2024] = { name = "Алхімічні знання Драконових островів", en = "Dragon Isles Alchemy Knowledge", desc = "Використовуйте знання, щоб опанувати спеціалізації алхімії.\n\nЗнання можна здобути різними способами: наприклад, уперше виготовивши рецепт або виконавши завдання, доступні на Ринку ремісників у Валдраккені.", den = "Use Knowledge to learn Alchemy Specializations.\n\nKnowledge can be gained through various means such as crafting recipes for the first time and completing quests offered in the Artisan's Market in Valdrakken." },
    [2025] = { name = "Кушнірські знання Драконових островів", en = "Dragon Isles Leatherworking Knowledge", desc = "Використовуйте знання, щоб опанувати спеціалізації кушнірства.\n\nЗнання можна здобути різними способами: наприклад, уперше виготовивши рецепт або виконавши завдання, доступні на Ринку ремісників у Валдраккені.", den = "Use Knowledge to learn Leatherworking Specializations.\n\nKnowledge can be gained through various means such as crafting recipes for the first time and completing quests offered in the Artisan's Market in Valdrakken." },
    [2026] = { name = "Кравецькі знання Драконових островів", en = "Dragon Isles Tailoring Knowledge", desc = "Використовуйте знання, щоб опанувати спеціалізації кравецтва.\n\nЗнання можна здобути різними способами: наприклад, уперше виготовивши рецепт або виконавши завдання, доступні на Ринку ремісників у Валдраккені.", den = "Use Knowledge to learn Tailoring Specializations.\n\nKnowledge can be gained through various means such as crafting recipes for the first time and completing quests offered in the Artisan's Market in Valdrakken." },
    [2027] = { name = "Інженерні знання Драконових островів", en = "Dragon Isles Engineering Knowledge", desc = "Використовуйте знання, щоб опанувати спеціалізації інженерії.\n\nЗнання можна здобути різними способами: наприклад, уперше виготовивши рецепт або виконавши завдання, доступні на Ринку ремісників у Валдраккені.", den = "Use Knowledge to learn Engineering Specializations.\n\nKnowledge can be gained through various means such as crafting recipes for the first time and completing quests offered in the Artisan's Market in Valdrakken." },
    [2028] = { name = "Знання письма Драконових островів", en = "Dragon Isles Inscription Knowledge", desc = "Використовуйте знання, щоб опанувати спеціалізації письма.\n\nЗнання можна здобути різними способами: наприклад, уперше виготовивши рецепт або виконавши завдання, доступні на Ринку ремісників у Валдраккені.", den = "Use Knowledge to learn Inscription Specializations.\n\nKnowledge can be gained through various means such as crafting recipes for the first time and completing quests offered in the Artisan's Market in Valdrakken." },
    [2029] = { name = "Ювелірні знання Драконових островів", en = "Dragon Isles Jewelcrafting Knowledge", desc = "Використовуйте знання, щоб опанувати спеціалізації ювелірства.\n\nЗнання можна здобути різними способами: наприклад, уперше виготовивши рецепт або виконавши завдання, доступні на Ринку ремісників у Валдраккені.", den = "Use Knowledge to learn Jewelcrafting Specializations.\n\nKnowledge can be gained through various means such as crafting recipes for the first time and completing quests offered in the Artisan's Market in Valdrakken." },
    [2030] = { name = "Знання зачаровування Драконових островів", en = "Dragon Isles Enchanting Knowledge", desc = "Використовуйте знання, щоб опанувати спеціалізації зачаровування.\n\nЗнання можна здобути різними способами: наприклад, уперше виготовивши рецепт або виконавши завдання, доступні на Ринку ремісників у Валдраккені.", den = "Use Knowledge to learn Enchanting Specializations.\n\nKnowledge can be gained through various means such as crafting recipes for the first time and completing quests offered in the Artisan's Market in Valdrakken." },
    [2031] = { name = "Експедиція Драконолуски", en = "Dragonscale Expedition", desc = "Надає репутацію з Експедицією Драконолуски.", den = "Grants Reputation with the Dragonscale Expedition." },
    [2032] = { name = "Торговельна плата", en = "Trader's Tender", desc = "Торговельну плату обмінюють на товари в Торговельній факторії.", den = "Trader's Tender is exchanged for goods with the Trading Post." },
    [2033] = { name = "Знання білування Драконових островів", en = "Dragon Isles Skinning Knowledge", desc = "Використовуйте знання, щоб опанувати спеціалізації білування.\n\nЗнання можна здобути різними способами: наприклад, вивчаючи відкриття, зроблені під час білування, або виконуючи завдання вашого наставника у Валдраккені.", den = "Use Knowledge to learn Skinning Specializations.\n\nKnowledge can be gained through various means such as studying discoveries found while skinning and completing quests offered by your trainer in Valdrakken." },
    [2034] = { name = "Травознавчі знання Драконових островів", en = "Dragon Isles Herbalism Knowledge", desc = "Використовуйте знання, щоб опанувати спеціалізації травознавства.\n\nЗнання можна здобути різними способами: наприклад, вивчаючи відкриття, зроблені під час збирання, або виконуючи завдання вашого наставника у Валдраккені.", den = "Use Knowledge to learn Herbalism Specializations.\n\nKnowledge can be gained through various means such as studying discoveries found while gathering and completing quests offered by your trainer in Valdrakken." },
    [2035] = { name = "Гірничі знання Драконових островів", en = "Dragon Isles Mining Knowledge", desc = "Використовуйте знання, щоб опанувати спеціалізації гірництва.\n\nЗнання можна здобути різними способами: наприклад, вивчаючи відкриття, зроблені під час видобутку, або виконуючи завдання вашого наставника у Валдраккені.", den = "Use Knowledge to learn Mining Specializations.\n\nKnowledge can be gained through various means such as studying discoveries found while mining and completing quests offered by your trainer in Valdrakken." },
