    [2650] = { name = "Смарагдова росинка", en = "Emerald Dewdrop", desc = "Роса, наповнена живильними властивостями Смарагдового Сну, здатна змусити будь-яку рослину розквітнути.\n\nВикористовується, щоб оживити рослини у Смарагдовому Сні.", den = "Dew infused with the nurturing properties of the Emerald Dream which can make any plant bloom.\n\nUsed to revitalize the plants in the Emerald Dream." },
    [2651] = { name = "Насіннєцвіт", en = "Seedbloom", desc = "Квіти рослин, наповнених сутністю Життєцвіту. Мають потужні естетичні та оживлювальні властивості.\n\nВикористовується, щоб придбати речі у Талії Шепітцвіт у Центральному таборі.", den = "The blooms from plants infused with Lifebloom Essence. These have powerful aesthetic and revitalizing properties.\n\nUsed to procure items from Talia Whisperbloom in the Central Encampment." },
