    [2657] = { name = "Таємничий уламок", en = "Mysterious Fragment", desc = "Здобувається за допомогу Азеротським Архіваріусам на Драконових островах. Принесіть їх постачальниці Арістті в Талдразусі, щоб обміняти на речі.", den = "Obtained by assisting the Azerothian Archivists in the Dragon Isles. Bring them to Provisioner Aristta in Thaldraszus to exchange for items." },
