    [2774] = { name = "10.2 Професії — Особистий лічильник — Випадання іскор С3 (прихований)", en = "10.2 Professions - Personal Tracker - S3 Spark Drops (Hidden)" },
    [2777] = { name = "Вливання Сну", en = "Dream Infusion", desc = "Використовується, щоб видобути сновидну сутність істоти.\n\nЕліанна в Центральному таборі зацікавилася б цим.", den = "Used to draw forth a creature's dreaming essence.\n\nElianna at the Central Encampment would be interested in this." },
    [2778] = { name = "Бронза", en = "Bronze", desc = "Безкінечні союзники Етернус торгують, використовуючи вільні нитки часу, стиснуті у бронзові монети.", den = "Eternus' Infinite allies trade using loose threads of time compressed into bronze coins." },
    [2780] = { name = "Лічильник Відлунної Ефемери [DNT]", en = "Echoed Ephemera Tracker [DNT]" },
    [2784] = { name = "10.2 Легендарний — Поступове просування — Лічильник", en = "10.2 Legendary - Progressive Advance - Tracker" },
    [2785] = { name = "Знання алхімії Каз Алґару", en = "Khaz Algar Alchemy Knowledge", desc = "Використовуйте знання, щоб вивчати спеціалізації алхімії.\n\nЗнання можна здобути різними способами, як-от уперше виготовивши рецепт або виконавши особливі ремісничі замовлення, що пропонують у Дорногалі.", den = "Use Knowledge to learn Alchemy Specializations.\n\nKnowledge can be gained through various means such as crafting recipes for the first time and completing special crafting orders offered in Dornogal." },
    [2786] = { name = "Знання ковальства Каз Алґару", en = "Khaz Algar Blacksmithing Knowledge", desc = "Використовуйте знання, щоб вивчати спеціалізації ковальства.\n\nЗнання можна здобути різними способами, як-от уперше виготовивши рецепт або виконавши особливі ремісничі замовлення, що пропонують у Дорногалі.", den = "Use Knowledge to learn Blacksmithing Specializations.\n\nKnowledge can be gained through various means such as crafting recipes for the first time and completing special crafting orders offered in Dornogal." },
    [2787] = { name = "Знання чаклунства Каз Алґару", en = "Khaz Algar Enchanting Knowledge", desc = "Використовуйте знання, щоб вивчати спеціалізації чаклунства.\n\nЗнання можна здобути різними способами, як-от уперше виготовивши рецепт або виконавши завдання, які пропонує ваш наставник у Дорногалі.", den = "Use Knowledge to learn Enchanting Specializations.\n\nKnowledge can be gained through various means such as crafting recipes for the first time and completing quests offered by your trainer in Dornogal." },
    [2788] = { name = "Знання інженерії Каз Алґару", en = "Khaz Algar Engineering Knowledge", desc = "Використовуйте знання, щоб вивчати спеціалізації інженерії.\n\nЗнання можна здобути різними способами, як-от уперше виготовивши рецепт або виконавши особливі ремісничі замовлення, що пропонують у Дорногалі.", den = "Use Knowledge to learn Engineering Specializations.\n\nKnowledge can be gained through various means such as crafting recipes for the first time and completing special crafting orders offered in Dornogal." },
    [2789] = { name = "Знання травництва Каз Алґару", en = "Khaz Algar Herbalism Knowledge", desc = "Використовуйте знання, щоб вивчати спеціалізації травництва.\n\nЗнання можна здобути різними способами, як-от вивчаючи відкриття, зроблені під час збирання, або виконавши завдання, які пропонує ваш наставник у Дорногалі.", den = "Use Knowledge to learn Herbalism Specializations.\n\nKnowledge can be gained through various means such as studying discoveries found while gathering and completing quests offered by your trainer in Dornogal." },
    [2790] = { name = "Знання письма Каз Алґару", en = "Khaz Algar Inscription Knowledge", desc = "Використовуйте знання, щоб вивчати спеціалізації письма.\n\nЗнання можна здобути різними способами, як-от уперше виготовивши рецепт або виконавши особливі ремісничі замовлення, що пропонують у Дорногалі.", den = "Use Knowledge to learn Inscription Specializations.\n\nKnowledge can be gained through various means such as crafting recipes for the first time and completing special crafting orders offered in Dornogal." },
    [2791] = { name = "Знання ювелірства Каз Алґару", en = "Khaz Algar Jewelcrafting Knowledge", desc = "Використовуйте знання, щоб вивчати спеціалізації ювелірства.\n\nЗнання можна здобути різними способами, як-от уперше виготовивши рецепт або виконавши особливі ремісничі замовлення, що пропонують у Дорногалі.", den = "Use Knowledge to learn Jewelcrafting Specializations.\n\nKnowledge can be gained through various means such as crafting recipes for the first time and completing special crafting orders offered in Dornogal." },
    [2792] = { name = "Знання шкіряної справи Каз Алґару", en = "Khaz Algar Leatherworking Knowledge", desc = "Використовуйте знання, щоб вивчати спеціалізації шкіряної справи.\n\nЗнання можна здобути різними способами, як-от уперше виготовивши рецепт або виконавши особливі ремісничі замовлення, що пропонують у Дорногалі.", den = "Use Knowledge to learn Leatherworking Specializations.\n\nKnowledge can be gained through various means such as crafting recipes for the first time and completing special crafting orders offered in Dornogal." },
    [2793] = { name = "Знання гірництва Каз Алґару", en = "Khaz Algar Mining Knowledge", desc = "Використовуйте знання, щоб вивчати спеціалізації гірництва.\n\nЗнання можна здобути різними способами, як-от вивчаючи відкриття, зроблені під час видобутку, або виконавши завдання, які пропонує ваш наставник у Дорногалі.", den = "Use Knowledge to learn Mining Specializations.\n\nKnowledge can be gained through various means such as studying discoveries found while mining and completing quests offered by your trainer in Dornogal." },
    [2794] = { name = "Знання білування Каз Алґару", en = "Khaz Algar Skinning Knowledge", desc = "Використовуйте знання, щоб вивчати спеціалізації білування.\n\nЗнання можна здобути різними способами, як-от вивчаючи відкриття, зроблені під час білування, або виконавши завдання, які пропонує ваш наставник у Дорногалі.", den = "Use Knowledge to learn Skinning Specializations.\n\nKnowledge can be gained through various means such as studying discoveries found while skinning and completing quests offered by your trainer in Dornogal." },
    [2795] = { name = "Знання кравецтва Каз Алґару", en = "Khaz Algar Tailoring Knowledge", desc = "Використовуйте знання, щоб вивчати спеціалізації кравецтва.\n\nЗнання можна здобути різними способами, як-от уперше виготовивши рецепт або виконавши особливі ремісничі замовлення, що пропонують у Дорногалі.", den = "Use Knowledge to learn Tailoring Specializations.\n\nKnowledge can be gained through various means such as crafting recipes for the first time and completing special crafting orders offered in Dornogal." },
    [2796] = { name = "Відроджений Сон", en = "Renascent Dream", desc = "Відроджений Сон заряджає Каталізатор відродження й дозволяє йому наділяти броню неймовірною силою.", den = "Renascent Dream charges the Revival Catalyst and allows it to imbue armor with incredible power." },
    [2797] = { name = "Трофей боротьби", en = "Trophy of Strife", desc = "Доказ вашої бойової вправності на Драконових островах. Здобувається зі щотижневого завдання «Іскри життя». Використовується для придбання спорядження Режиму війни.", den = "Proof of your combat prowess throughout the Dragon Isles. Acquired from the Sparks of Life weekly quest. Used to purchase War Mode gear." },
    [2799] = { name = "[DNT] Невидима валюта Жукоранчо", en = "[DNT] Beetle Ranch Invisible Currency" },
    [2800] = { name = "10.2.6 Професії — Особистий лічильник — Випадання іскор С4 (прихований)", en = "10.2.6 Professions - Personal Tracker - S4 Spark Drops (Hidden)" },
    [2803] = { name = "Підземна монета", en = "Undercoin", desc = "Валюта, якою зазвичай користуються дослідники, що прагнуть обмінятися таємницями й оповідями про багатства.", den = "A currency commonly used by explorers looking to trade secrets and tales of wealth." },
    [2805] = { name = "Пробуджений герб маляти", en = "Whelpling's Awakened Crest", desc = "Здобувається з багатьох зовнішніх активностей, рейдів Пошуку рейду та героїчних підземель упродовж 4-го сезону Dragonflight.", den = "Earned from many outdoor activities, Raid Finder raids, and Heroic dungeons during Dragonflight Season 4." },
    [2806] = { name = "Пробуджений герб маляти", en = "Whelpling's Awakened Crest", desc = "Здобувається з багатьох зовнішніх активностей, рейдів Пошуку рейду та героїчних підземель упродовж 4-го сезону Dragonflight.", den = "Earned from many outdoor activities, Raid Finder raids, and Heroic dungeons during Dragonflight Season 4." },
    [2807] = { name = "Пробуджений герб дрейка", en = "Drake's Awakened Crest", desc = "Здобувається з деяких зовнішніх активностей, рейдів звичайної складності та підземель Міфік 0 упродовж 4-го сезону Dragonflight.", den = "Earned from some outdoor activities, Normal difficulty raids, and Mythic 0 dungeons during Dragonflight Season 4." },
    [2808] = { name = "Пробуджений герб дрейка", en = "Drake's Awakened Crest", desc = "Здобувається з деяких зовнішніх активностей, рейдів звичайної складності та підземель Міфік 0 упродовж 4-го сезону Dragonflight.", den = "Earned from some outdoor activities, Normal difficulty raids, and Mythic 0 dungeons during Dragonflight Season 4." },
    [2809] = { name = "Пробуджений герб вірма", en = "Wyrm's Awakened Crest", desc = "Здобувається з рейдів героїчної складності та підземель з міфічним ключем-каменем до +5 упродовж 4-го сезону Dragonflight.", den = "Earned from Heroic difficulty raids and Mythic Keystone dungeons up to +5 during Dragonflight Season 4." },
    [2810] = { name = "Пробуджений герб вірма", en = "Wyrm's Awakened Crest", desc = "Здобувається з рейдів героїчної складності та підземель з міфічним ключем-каменем до +5 упродовж 4-го сезону Dragonflight.", den = "Earned from Heroic difficulty raids and Mythic Keystone dungeons up to +5 during Dragonflight Season 4." },
    [2811] = { name = "Пробуджений герб аспекта", en = "Aspect's Awakened Crest", desc = "Здобувається з рейдів міфічної складності та підземель з міфічним ключем-каменем від +6 і вище упродовж 4-го сезону Dragonflight.", den = "Earned from Mythic difficulty raids and Mythic Keystone dungeons from +6 and up during Dragonflight Season 4." },
    [2812] = { name = "Пробуджений герб аспекта", en = "Aspect's Awakened Crest", desc = "Здобувається з рейдів міфічної складності та підземель з міфічним ключем-каменем від +6 і вище упродовж 4-го сезону Dragonflight.", den = "Earned from Mythic difficulty raids and Mythic Keystone dungeons from +6 and up during Dragonflight Season 4." },
    [2813] = { name = "Гармонізований шовк", en = "Harmonized Silk", desc = "Гармонізований шовк заряджає Каталізатор і дає йому змогу наділяти обладунки неймовірною силою.", den = "Harmonized Silk charges the Catalyst and allows it to imbue armor with incredible power." },
    [2814] = { name = "Визнання — Команда Барильця", en = "Renown-Keg Leg's Crew", desc = "Надає репутацію з Командою Барильця.", den = "Grants Reputation with the Keg Leg's Crew." },
    [2815] = { name = "Кристали резонансу", en = "Resonance Crystals", desc = "Сформовані енергіями Душі світу, що взаємодіють з каменем у Каз Алґарі та під ним, ці шановані об'єкти використовуються для придбання нагород, відкритих за визнання.", den = "Formed by the energies of the Worldsoul interacting with the stone in and beneath Khaz Algar, these revered objects are used to purchase rewards unlocked from renown." },
    [2819] = { name = "Архіви Азерота", en = "Azerothian Archives", desc = "Поступ серед Архіваріусів Азерота.", den = "Progress with the Azerothian Archivists." },
