    [2901] = { name = "Визнання — Араті Голловфоллу", en = "Renown - Hallowfall Arathi", desc = "Араті з Експедиції Голловфоллу оберігають зорю Беледар від численних загроз, що ховаються під Каз Алґаром. Відрізані від своєї заморської імперії, вони збудували новий дім силою своєї віри у Священне Полум'я.", den = "The Arathi of the Hallowfall Expedition safeguard the star Beledar from the many threats found under Khaz Algar. Cut off from their overseas empire, they have built a new home with the strength of their faith in the Sacred Flame." },
