    [3093] = { name = "Оздоба нерубарів", en = "Nerub-ar Finery", desc = "Прикрашаючи обладунки відданих, ці відзнаки є символом вищого світу серед привілейованих мешканців Нерубару.\n\nУ палаці Ануб'азал може потайки передавати їх Розітнутим ниткам, а натомість зміцнювати ваш наступ.", den = "Adorning the armor of the devoted, these insignias are a symbol of high society among the privileged inhabitants of Nerub-ar.\n\nInside the palace, Anub'azal can smuggle these out to The Severed Threads and in exchange, strengthen your assault." },
