    [3100] = { name = "Жетон Бронзового святкування", en = "Bronze Celebration Token", desc = "Здобувається за щотижневі заняття під час 20-го Бронзового святкування. Обмінюється на нові речі на Бронзовому святкуванні біля Печер Часу.", den = "Earned from weekly activities during the 20th Bronze Celebration. Exchanged for new items at the Bronze Celebration outside the Caverns of Time." },
    [3102] = { name = "Жетон Бронзового святкування", en = "Bronze Celebration Token", desc = "Здобувається за щотижневі заняття під час 20-го Бронзового святкування. Обмінюється на нові речі на Бронзовому святкуванні біля Печер Часу.", den = "Earned from weekly activities during the 20th Bronze Celebration. Exchanged for new items at the Bronze Celebration outside the Caverns of Time." },
