    [3107] = { name = "Звітрений герб Надкопальні", en = "Weathered Undermine Crest", desc = "Використовується для покращення спорядження Шукача пригод і Ветерана в 2-му сезоні The War Within до рівня предметів 623-632. Здобувається за такі заняття:\n\n- Повторювані події на відкритому світі\n- Пошук рейду: Визволення Надкопальні\n- Героїчні сезонні підземелля\n- Глибини (рівні 1-5)", den = "Used to upgrade Adventurer and Veteran gear in War Within Season 2 up to item levels 623-632. Earned from the following activities:\n\n- Repeatable Outdoor Events\n- Raid Finder Liberation of Undermine\n- Heroic Season Dungeons\n- Delves (Tiers 1 to 5)" },
    [3108] = { name = "Різьблений герб Надкопальні", en = "Carved Undermine Crest", desc = "Використовується для покращення спорядження Ветерана і Чемпіона в 2-му сезоні The War Within до рівня предметів 636-645. Здобувається за такі заняття:\n\n- Щотижневі події на відкритому світі\n- Звичайне Визволення Надкопальні\n- Міфічні сезонні підземелля\n- Глибини (рівні 6 і 7)\n- Винагорода глибинника (рівні 4 і 5)", den = "Used to upgrade Veteran and Champion gear in War Within Season 2 up to item levels 636-645. Earned from the following activities:\n\n- Weekly Outdoor Events\n- Normal Liberation of Undermine\n- Mythic Season Dungeons\n- Delves (Tiers 6 and 7)\n- Delver's Bounty (Tiers 4 and 5)" },
    [3109] = { name = "Рунний герб Надкопальні", en = "Runed Undermine Crest", desc = "Використовується для покращення спорядження Чемпіона і Героя в 2-му сезоні The War Within до рівня предметів 649-658. Здобувається за такі заняття:\n\n- Героїчне Визволення Надкопальні\n- Підземелля з міфічним ключем від +2 до +6\n- Глибини (рівні 8-11)\n- Винагорода глибинника (рівні 6 і 7)", den = "Used to upgrade Champion and Hero gear in War Within Season 2 up to item levels 649-658. Earned from the following activities:\n\n- Heroic Liberation of Undermine\n- Mythic Keystone Dungeons from +2 to +6\n- Delves (Tiers 8 to 11)\n- Delver's Bounty (Tiers 6 and 7)" },
    [3110] = { name = "Позолочений герб Надкопальні", en = "Gilded Undermine Crest", desc = "Використовується для покращення спорядження Героя і Міфу в 2-му сезоні The War Within до рівня предметів 662 і вище. Здобувається за такі заняття:\n\n- Міфічне Визволення Надкопальні\n- Підземелля з міфічним ключем від +7 і вище\n- Позолочена схованка Глибин (рівень 11)\n- Винагорода глибинника (рівень 8 і вище)", den = "Used to upgrade Hero and Myth gear in War Within Season 2 up to item levels 662 and above. Earned from the following activities:\n\n- Mythic Liberation of Undermine\n- Mythic Keystone Dungeons from +7 and up\n- Delve's Gilded Stash (Tier 11)\n- Delver's Bounty (Tier 8 and up)" },
