    [3141] = { name = "Пил зоряних іскор", en = "Starlight Spark Dust", desc = "Магічний залишок, який отримують разом із Розколотими іскрами зоряного світла. Використовується, щоб відстежувати, скільки Розколотих іскор зоряного світла ви здобули в 3-му сезоні The War Within.\n\nЯкщо ви відстаєте за кількістю Розколотих іскор зоряного світла, наздогнати допоможе проходження контенту максимального рівня, як-от Глибини, Міфік+, рейди, інстансований PvP та деякі події на відкритому світі.", den = "Magical residue obtained alongside Fractured Sparks of Starlight. Used to track how many Fractured Sparks of Starlight you have obtained so far in The War Within Season 3.\n\nIf you fall behind on Fractured Sparks of Starlight, completing max-level content such as Delves, Mythic Plus, Raids, Instanced PvP, and some outdoor events may help you catch up." },
    [3142] = { name = "EVERGREEN Glibyny - Лічильник - EoD Account Rewards - Тижнева межа", en = "EVERGREEN Delves - Tracker - EoD Account Rewards - Weekly Cap", desc = "Гравці мають отримувати досвід Подорожі глибинника і супутника з нагород Щедрої глибини лише 28 разів на тиждень на акаунт. А саме нагороди за завершення забігу, що видаються після проходження сценарію. Нагороди зі скринь зі скарбами цією межею не обмежені.", den = "Players should only recive the Delver's Journey and Companion EXP from Bountiful Delve Rewards 28 times a week per accoun. Specificaly the End Of Run rewards pushed upon scenario completion. Treasure Chest Rewards are not bound by this cap." },
    [3143] = { name = "11.0 Глибини — Трекер щедрості — Ліміт Подорожі дослідника", en = "11.0 Delves - Bountiful Tracker - Delver's Journey Cap" },
