    [3149] = { name = "Зміщені опоганені пам'ятки", en = "Displaced Corrupted Mementos", desc = "Уламки спогадів із Жахливих видінь Н'Зота, які можна дослідити в Титанічному дослідницькому архіві в Серцевій палаті.", den = "Fragments of memory from Horrific Visions of N'Zoth which can be analyzed at the Titanic Research Archive in the Chamber of Heart." },
    [3150] = { name = "Знання алхімії Опівночі", en = "Midnight Alchemy Knowledge", desc = "Використовуйте знання, щоб вивчати спеціалізації алхімії.\n\nЗнання можна здобути різними способами, як-от перше виготовлення рецептів і виконання особливих замовлень на виготовлення в Сільвермуні.", den = "Use Knowledge to learn Alchemy Specializations.\n\nKnowledge can be gained through various means such as crafting recipes for the first time and completing special crafting orders offered in Silvermoon City." },
    [3151] = { name = "Знання ковальства Опівночі", en = "Midnight Blacksmithing Knowledge", desc = "Використовуйте знання, щоб вивчати спеціалізації ковальства.\n\nЗнання можна здобути різними способами, як-от перше виготовлення рецептів і виконання особливих замовлень на виготовлення в Сільвермуні.", den = "Use Knowledge to learn Blacksmithing Specializations.\n\nKnowledge can be gained through various means such as crafting recipes for the first time and completing special crafting orders offered in Silvermoon City." },
    [3152] = { name = "Знання накладання чарів Опівночі", en = "Midnight Enchanting Knowledge", desc = "Використовуйте знання, щоб вивчати спеціалізації накладання чарів.\n\nЗнання можна здобути різними способами, як-от перше виготовлення рецептів і виконання завдань, які пропонує ваш наставник у Сільвермуні.", den = "Use Knowledge to learn Enchanting Specializations.\n\nKnowledge can be gained through various means such as crafting recipes for the first time and completing quests offered by your trainer in Silvermoon City." },
    [3153] = { name = "Знання інженерії Опівночі", en = "Midnight Engineering Knowledge", desc = "Використовуйте знання, щоб вивчати спеціалізації інженерії.\n\nЗнання можна здобути різними способами, як-от перше виготовлення рецептів і виконання особливих замовлень на виготовлення в Сільвермуні.", den = "Use Knowledge to learn Engineering Specializations.\n\nKnowledge can be gained through various means such as crafting recipes for the first time and completing special crafting orders offered in Silvermoon City." },
    [3154] = { name = "Знання травництва Опівночі", en = "Midnight Herbalism Knowledge", desc = "Використовуйте знання, щоб вивчати спеціалізації травництва.\n\nЗнання можна здобути різними способами, як-от вивчення відкриттів, зроблених під час збирання, і виконання завдань, які пропонує ваш наставник у Сільвермуні.", den = "Use Knowledge to learn Herbalism Specializations.\n\nKnowledge can be gained through various means such as studying discoveries found while gathering and completing quests offered by your trainer in Silvermoon City." },
    [3155] = { name = "Знання письмівства Опівночі", en = "Midnight Inscription Knowledge", desc = "Використовуйте знання, щоб вивчати спеціалізації письмівства.\n\nЗнання можна здобути різними способами, як-от перше виготовлення рецептів і виконання особливих замовлень на виготовлення в Сільвермуні.", den = "Use Knowledge to learn Inscription Specializations.\n\nKnowledge can be gained through various means such as crafting recipes for the first time and completing special crafting orders offered in Silvermoon City." },
    [3156] = { name = "Знання ювелірства Опівночі", en = "Midnight Jewelcrafting Knowledge", desc = "Використовуйте знання, щоб вивчати спеціалізації ювелірства.\n\nЗнання можна здобути різними способами, як-от перше виготовлення рецептів і виконання особливих замовлень на виготовлення в Сільвермуні.", den = "Use Knowledge to learn Jewelcrafting Specializations.\n\nKnowledge can be gained through various means such as crafting recipes for the first time and completing special crafting orders offered in Silvermoon City." },
    [3157] = { name = "Знання шкіряної справи Опівночі", en = "Midnight Leatherworking Knowledge", desc = "Використовуйте знання, щоб вивчати спеціалізації шкіряної справи.\n\nЗнання можна здобути різними способами, як-от перше виготовлення рецептів і виконання особливих замовлень на виготовлення в Сільвермуні.", den = "Use Knowledge to learn Leatherworking Specializations.\n\nKnowledge can be gained through various means such as crafting recipes for the first time and completing special crafting orders offered in Silvermoon City." },
    [3158] = { name = "Знання гірництва Опівночі", en = "Midnight Mining Knowledge", desc = "Використовуйте знання, щоб вивчати спеціалізації гірництва.\n\nЗнання можна здобути різними способами, як-от вивчення відкриттів, зроблених під час видобутку, і виконання завдань, які пропонує ваш наставник у Сільвермуні.", den = "Use Knowledge to learn Mining Specializations.\n\nKnowledge can be gained through various means such as studying discoveries found while mining and completing quests offered by your trainer in Silvermoon City." },
    [3159] = { name = "Знання білування Опівночі", en = "Midnight Skinning Knowledge", desc = "Використовуйте знання, щоб вивчати спеціалізації білування.\n\nЗнання можна здобути різними способами, як-от вивчення відкриттів, зроблених під час білування, і виконання завдань, які пропонує ваш наставник у Сільвермуні.", den = "Use Knowledge to learn Skinning Specializations.\n\nKnowledge can be gained through various means such as studying discoveries found while skinning and completing quests offered by your trainer in Silvermoon City." },
    [3160] = { name = "Знання кравецтва Опівночі", en = "Midnight Tailoring Knowledge", desc = "Використовуйте знання, щоб вивчати спеціалізації кравецтва.\n\nЗнання можна здобути різними способами, як-от перше виготовлення рецептів і виконання особливих замовлень на виготовлення в Сільвермуні.", den = "Use Knowledge to learn Tailoring Specializations.\n\nKnowledge can be gained through various means such as crafting recipes for the first time and completing special crafting orders offered in Silvermoon City." },
