    [3216] = { name = "Рештки здобичі", en = "Bounty's Remnants", desc = "Здобувається за проходження щедрих Глибин. Витратьте 100 Решток здобичі, щоб відкрити Прихований скарб. Його вміст залежить від рівня пройденої Глибини.", den = "Obtained from completing bountiful delves. Use 100 Bounty's Remnants to open a Hidden Trove. It's contents depend on the completed Delve's Tier." },
    [3218] = { name = "Порожня бляшанка Каджа-Коли", en = "Empty Kaja'Cola Can", desc = "Порожня бляшанка з-під Каджа-Коли. Їх часто можна знайти в купах С.М.І.Т.Т.Я. Анджело Ржабак у штабі С.М.І.Т.Т.Я зацікавиться цим.", den = "An empty can of Kaja'Cola. These are commonly found in S.C.R.A.P Heaps. Angelo Rustbin at S.C.R.A.P Headquarters would be interested in this." },
    [3220] = { name = "Старовинна бляшанка Каджа-Коли", en = "Vintage Kaja'Cola Can", desc = "Старовинна бляшанка Каджа-Коли. Їх рідко можна знайти в купах С.М.І.Т.Т.Я. Анджело Ржабак у штабі С.М.І.Т.Т.Я зацікавиться цим.", den = "A can of vintage Kaja'Cola. These are rarely found in S.C.R.A.P Heaps. Angelo Rustbin at S.C.R.A.P Headquarters would be interested in this." },
    [3221] = { name = "Репутація з гоблінськими картелями", en = "Goblin Cartels Reputation", desc = "Дає репутацію з обраним гоблінським картелем.", den = "Grants rep with an aligned Goblin Cartel." },
