    [3226] = { name = "Маркетингове дослідження", en = "Market Research", desc = "Рішення Темнозапалу шукають маркетингові дослідження, щоб з'ясувати, на чому зосередити свою діяльність. Ви можете обміняти це в Сітча Лоудауна на Халупному пагорбі, щоб заробити репутацію з його картелем.", den = "Darkfuse Solutions is on the lookout for market research to find where to focus their activities. You can exchange this with Sitch Lowdown at Hovel Hill to earn reputation with their cartel." },
