    [3250] = { name = "Гранований кристалічний ск'верн", en = "Faceted Crystalline Fel", desc = "Самоцвіт, що пульсує забороненою звабою, схований глибоко в тінях Алеї Вбивць. Дехто з торгівців убив би за нього!", den = "A gem pulsing with forbidden allure, hidden deep within the shadows of Murder Row. Some vendors would kill for this!" },
    [3251] = { name = "Ск'вернокована бронза", en = "Felforged Bronze", desc = "Часточка часу, спресована в бронзову монету й осквернена Палаючим Легіоном. Моментус може використати її, щоб покращити ваше спорядження, або обміняйте її в Лідаморрутту на шанс отримати потужні реліквії та сувеніри безмежної сили.", den = "A mote of time compressed into a bronze coin and corrupted by the Burning Legion. Momentus can use this to upgrade your gear, or trade this to Lidamorrutu for a chance at powerful relics and mementos of infinite power." },
    [3253] = { name = "EVERGREEN Delves - Tracker - Mislaid Curiosity - Weekly Cap", en = "EVERGREEN Delves - Tracker - Mislaid Curiosity - Weekly Cap", desc = "Загублені дивовижі дають додаткову здобич, якщо Глибина щедра. Ця валюта запобігає такому експлойту: гравець проходить 27 з 28 щедрих Глибин за тиждень. Гравець заходить у 28-му щедру Глибину й забирає всі щедрі Загублені дивовижі, не проходячи Глибину. Виходить і заходить знову, щоб набрати ще щедрих Загублених дивовиж. І так нескінченно, якби не ліміт.", den = "Mislaid Curiosities grant bonus loot if a delve is bountiful. This currency served to prevent the following exploit: Player completes 27 out of 28 bountiful delves for the week. Player enters the 28th Bountiful Delve and loots all bountiful Mislaid Curiosities without completing the delve. Leaves the delve and re-enters to pick up more bountiful Mislaid Curiosities. Rince and repeat infintly if not for the cap." },
    [3254] = { name = "Тестова валюта Чейза [DNT]", en = "Chase's Test Currency [DNT]" },
    [3256] = { name = "Завзяття алхіміка-майстра", en = "Artisan Alchemist's Moxie", desc = "Використовується для вивчення чи купівлі рецептів алхімії Опівночі, придбання одноразових томів знань у торгівців визнання Опівночі та отримання високоякісних реагентів.", den = "Used for learning or purchasing Midnight Alchemy recipes, acquiring single-use tomes of Knowledge from Midnight Renowns, and obtaining high-quality reagents." },
    [3257] = { name = "Завзяття коваля-майстра", en = "Artisan Blacksmith's Moxie", desc = "Використовується для купівлі рецептів ковальства Опівночі, придбання одноразових томів знань у торгівців визнання Опівночі та отримання високоякісних реагентів.", den = "Used for purchasing Midnight Blacksmithing recipes, acquiring single-use tomes of Knowledge from Midnight Renowns, and obtaining high-quality reagents." },
    [3258] = { name = "Завзяття зачаровувача-майстра", en = "Artisan Enchanter's Moxie", desc = "Використовується для купівлі рецептів зачаровування Опівночі, придбання одноразових томів знань у торгівців визнання Опівночі та отримання високоякісних реагентів.", den = "Used for purchasing Midnight Enchanting recipes, acquiring single-use tomes of Knowledge from Midnight Renowns, and obtaining high-quality reagents." },
    [3259] = { name = "Завзяття інженера-майстра", en = "Artisan Engineer's Moxie", desc = "Використовується для купівлі рецептів інженерії Опівночі, придбання одноразових томів знань у торгівців визнання Опівночі та отримання високоякісних реагентів.", den = "Used for purchasing Midnight Engineering recipes, acquiring single-use tomes of Knowledge from Midnight Renowns, and obtaining high-quality reagents." },
