    [3263] = { name = "Завзяття шкіряра-майстра", en = "Artisan Leatherworker's Moxie", desc = "Використовується для купівлі рецептів шкіряної справи Опівночі, придбання одноразових томів знань у торгівців визнання Опівночі та отримання високоякісних реагентів.", den = "Used for purchasing Midnight Leatherworking recipes, acquiring single-use tomes of Knowledge from Midnight Renowns, and obtaining high-quality reagents." },
