    [3265] = { name = "Завзяття чинбаря-майстра", en = "Artisan Skinner's Moxie", desc = "Можна обміняти на високоякісні реагенти та одноразові томи знань у торгівців визнання Опівночі.", den = "Can be exchanged for high-quality reagents and single-use tomes of Knowledge from Midnight Renowns." },
    [3266] = { name = "Завзяття кравця-майстра", en = "Artisan Tailor's Moxie", desc = "Використовується для купівлі рецептів кравецтва Опівночі, придбання одноразових томів знань у торгівців визнання Опівночі та отримання високоякісних реагентів.", den = "Used for purchasing Midnight Tailoring recipes, acquiring single-use tomes of Knowledge from Midnight Renowns, and obtaining high-quality reagents." },
    [3267] = { name = "Ск'вернокована бронза", en = "Felforged Bronze", desc = "Часточка часу, спресована в бронзову монету й осквернена Палаючим Легіоном. Моментус може використати її, щоб покращити ваше спорядження, або обміняйте її в Лідаморрутту на шанс отримати потужні реліквії та сувеніри безмежної сили.", den = "A mote of time compressed into a bronze coin and corrupted by the Burning Legion. Momentus can use this to upgrade your gear, or trade this to Lidamorrutu for a chance at powerful relics and mementos of infinite power." },
    [3269] = { name = "Ефірна скалка Порожнечі", en = "Ethereal Voidsplinter", desc = "Ефірні скалки Порожнечі заряджають Каталізатор і дають йому змогу наповнювати обладунки неймовірною силою. Повільно накопичуються кожні два тижні.", den = "Ethereal Voidsplinters charge the Catalyst and allow it to imbue armor with incredible power. Slowly accumulates every two weeks." },
    [3270] = { name = "11.2 Глибини — Особистий трекер — S3 Щотижнева здача Елізі (Приховано)", en = "11.2 Delves - Personal Tracker - S3 Weekly Elise Turn-In(Hidden)" },
