    [3278] = { name = "Ефірні нитки", en = "Ethereal Strands", desc = "Нитки, наповнені потужною таємною енергією. Їх можна використати, щоб посилити здатності Накидки Реші вбирати енергію.", den = "Threads imbued with powerful arcane energy. These can be used to enhance the energy harnessing abilities of the Reshii Wraps." },
    [3279] = { name = "11. Слава рейду — Галаджіо — Трекер акаунта рейдового підсилення", en = "11. Raid Renown - Gallagio - Raid Buff Acct Tracker" },
