    [3282] = { name = "Клуб винагород за лояльність Галаджо", en = "Gallagio Loyalty Rewards Club", desc = "Дає репутацію з Клубом винагород за лояльність Галаджо.", den = "Grants Reputation with the Gallagio Loyalty Rewards Club." },
    [3283] = { name = "Сяйво Полум'я", en = "Flame's Radiance", desc = "Дає репутацію зі Сяйвом Полум'я.", den = "Grants Reputation with Flame's Radiance." },
    [3284] = { name = "Потьмянілий ефірний герб", en = "Weathered Ethereal Crest", desc = "Використовується для покращення спорядження Шукача пригод і Ветерана в 3-му сезоні The War Within до рівня предметів 108-118. Здобувається за такі заняття:\n\n- Повторювані події у відкритому світі\n- Пошук рейду Манокузня Омега\n- Героїчні сезонні підземелля\n- Глибини (рівні 1-5)", den = "Used to upgrade Adventurer and Veteran gear in War Within Season 3 up to item levels 108-118. Earned from the following activities:\n\n- Repeatable Outdoor Events\n- Raid Finder Manaforge Omega\n- Heroic Season Dungeons\n- Delves (Tiers 1 to 5)" },
    [3285] = { name = "Потьмянілий ефірний герб", en = "Weathered Ethereal Crest", desc = "Використовується для покращення спорядження Шукача пригод і Ветерана в 3-му сезоні The War Within до рівня предметів 108-118. Здобувається за такі заняття:\n\n- Повторювані події у відкритому світі\n- Пошук рейду Манокузня Омега\n- Героїчні сезонні підземелля\n- Глибини (рівні 1-5)", den = "Used to upgrade Adventurer and Veteran gear in War Within Season 3 up to item levels 108-118. Earned from the following activities:\n\n- Repeatable Outdoor Events\n- Raid Finder Manaforge Omega\n- Heroic Season Dungeons\n- Delves (Tiers 1 to 5)" },
    [3286] = { name = "Різьблений астральний герб", en = "Carved Ethereal Crest", desc = "Використовується для покращення спорядження ветерана та чемпіона в 3-му сезоні The War Within до рівня предметів 121-131. Здобувається за такі дії:\n\n- Щотижневі події у відкритому світі\n- Манокузня «Омега» (звичайний)\n- Підземелля сезону (міфічні)\n- Провалля (рівні 6 і 7)\n- Винагорода дослідника глибин (рівні 4 і 5)", den = "Used to upgrade Veteran and Champion gear in War Within Season 3 up to item levels 121-131. Earned from the following activities:\n\n- Weekly Outdoor Events\n- Normal Manaforge Omega\n- Mythic Season Dungeons\n- Delves (Tiers 6 and 7)\n- Delver's Bounty (Tiers 4 and 5)" },
    [3287] = { name = "Різьблений астральний герб", en = "Carved Ethereal Crest", desc = "Використовується для покращення спорядження ветерана та чемпіона в 3-му сезоні The War Within до рівня предметів 121-131. Здобувається за такі дії:\n\n- Щотижневі події у відкритому світі\n- Манокузня «Омега» (звичайний)\n- Підземелля сезону (міфічні)\n- Провалля (рівні 6 і 7)\n- Винагорода дослідника глибин (рівні 4 і 5)", den = "Used to upgrade Veteran and Champion gear in War Within Season 3 up to item levels 121-131. Earned from the following activities:\n\n- Weekly Outdoor Events\n- Normal Manaforge Omega\n- Mythic Season Dungeons\n- Delves (Tiers 6 and 7)\n- Delver's Bounty (Tiers 4 and 5)" },
    [3288] = { name = "Рунний астральний герб", en = "Runed Ethereal Crest", desc = "Використовується для покращення спорядження чемпіона та героя в 3-му сезоні The War Within до рівня предметів 134-144. Здобувається за такі дії:\n\n- Манокузня «Омега» (героїчний)\n- Підземелля з міфічним ключем-каменем від +2 до +6\n- Провалля (рівні 8-11)\n- Винагорода дослідника глибин (рівні 6 і 7)", den = "Used to upgrade Champion and Hero gear in War Within Season 3 up to item levels 134-144. Earned from the following activities:\n\n- Heroic Manaforge Omega\n- Mythic Keystone Dungeons from +2 to +6\n- Delves (Tiers 8 to 11)\n- Delver's Bounty (Tiers 6 and 7)" },
    [3289] = { name = "Рунний астральний герб", en = "Runed Ethereal Crest", desc = "Використовується для покращення спорядження чемпіона та героя в 3-му сезоні The War Within до рівня предметів 134-144. Здобувається за такі дії:\n\n- Манокузня «Омега» (героїчний)\n- Підземелля з міфічним ключем-каменем від +2 до +6\n- Провалля (рівні 8-11)\n- Винагорода дослідника глибин (рівні 6 і 7)", den = "Used to upgrade Champion and Hero gear in War Within Season 3 up to item levels 134-144. Earned from the following activities:\n\n- Heroic Manaforge Omega\n- Mythic Keystone Dungeons from +2 to +6\n- Delves (Tiers 8 to 11)\n- Delver's Bounty (Tiers 6 and 7)" },
    [3290] = { name = "Золочений астральний герб", en = "Gilded Ethereal Crest", desc = "Використовується для покращення спорядження героя та міфічного спорядження в 3-му сезоні The War Within до рівня предметів 147 і вище. Здобувається за такі дії:\n\n- Манокузня «Омега» (міфічний)\n- Підземелля з міфічним ключем-каменем від +7 і вище\n- Золочений скарб провалля (рівень 11)\n- Винагорода дослідника глибин (рівень 8 і вище)", den = "Used to upgrade Hero and Myth gear in War Within Season 3 up to item levels 147 and above. Earned from the following activities:\n\n- Mythic Manaforge Omega\n- Mythic Keystone Dungeons from +7 and up\n- Delve's Gilded Stash (Tier 11)\n- Delver's Bounty (Tier 8 and up)" },
    [3291] = { name = "Золочений астральний герб", en = "Gilded Ethereal Crest", desc = "Використовується для покращення спорядження героя та міфічного спорядження в 3-му сезоні The War Within до рівня предметів 147 і вище. Здобувається за такі дії:\n\n- Манокузня «Омега» (міфічний)\n- Підземелля з міфічним ключем-каменем від +7 і вище\n- Золочений скарб провалля (рівень 11)\n- Винагорода дослідника глибин (рівень 8 і вище)", den = "Used to upgrade Hero and Myth gear in War Within Season 3 up to item levels 147 and above. Earned from the following activities:\n\n- Mythic Manaforge Omega\n- Mythic Keystone Dungeons from +7 and up\n- Delve's Gilded Stash (Tier 11)\n- Delver's Bounty (Tier 8 and up)" },
    [3293] = { name = "Пам'ятка епохи", en = "Epoch Memento", desc = "Крихітна частинка історії однієї епохи.", den = "A tiny piece of an epoch story." },
    [3303] = { name = "Невіддана монета", en = "Untethered Coin", desc = "Дивна монета, знайдена у Невідданому просторі на К'ареші. Шад'аніс на Видноколі Зо'Шуул зацікавиться нею в обмін на іграшки, прикраси, улюбленців тощо. Здобувається за виконання завдання «Більше, ніж просто фаза».", den = "A strange coin found within Untethered Space on K'aresh. Shad'anis at Overlook Zo'Shuul will be interested in this in exchange for toys, cosmetics, pets, and more. Earned by completing the quest \"More Than Just a Phase.\"" },
    [3304] = { name = "Вандали Манокузні", en = "Manaforge Vandals", desc = "Дає репутацію з Вандалами Манокузні.", den = "Grants Reputation with the Manaforge Vandals." },
    [3305] = { name = "Визнання — Вандали Манокузні", en = "Renown - Manaforge Vandals", desc = "[DNT]", den = "[DNT]" },
    [3306] = { name = "Вандали Манокузні", en = "Manaforge Vandals", desc = "Дає репутацію з Вандалами Манокузні.", den = "Grants Reputation with the Manaforge Vandals." },
    [3307] = { name = "11.2 Слава рейду — Манакузня — Трекер акаунта рейдового підсилення", en = "11.2 Raid Renown - Manaforge - Raid Buff Acct Tracker" },
    [3308] = { name = "11.2 Слава рейду — Манакузня — Трекер акаунта підсилення швидкості", en = "11.2 Raid Renown - Manaforge Speed Buff Acct Tracker" },
    [3309] = { name = "Скалка пекельного каменю", en = "Hellstone Shard", desc = "Здобувається за дії під час події «Жадібний емісар». Обмінюється на пекельні комплекти обладунків у Баранара в Дорногалі.", den = "Earned from activities during the Greedy Emissary event. Exchanged for hellish armorsets with Baranar in Dornogal." },
    [3310] = { name = "Скалки ключа від скрині", en = "Coffer Key Shards", desc = "Здобуваються зі скарбів, світових завдань і подій відкритого світу в зонах Опівночі. Під час входу в провалля 100 скалок об'єднуються у відновлений ключ від скрині.", den = "Acquired from treasures, World Quests, and outdoor events throughout Midnight Zones. Entering a Delve combines 100 shards into a Restored Coffer Key." },
    [3313] = { name = "11. Слава Рейду — Ґалладжіо — Трекер Рейдового Підсилення Акаунта", en = "11. Raid Renown - Gallagio - Raid Buff Acct Tracker" },
    [3314] = { name = "11. Слава Рейду — Ґалладжіо — Трекер Підсилення Швидкості Акаунта", en = "11. Raid Renown - Gallagio - Speed Buff Acct Tracker" },
    [3315] = { name = "Визнання — Клуб лояльності «Ґалладжіо»", en = "Renown - Gallagio Loyalty Rewards Club", desc = "[DNT]", den = "[DNT]" },
    [3316] = { name = "Пил світла Порожнечі", en = "Voidlight Marl", desc = "Створена на злитті Світла та Порожнечі, ця містична речовина обмінюється на об'єкти подібної значущості.\n\nВикористовується у скарбників визнання та інших торговців у зонах Опівночі.", den = "Created at the confluence of Light and Void, this mystical substance may be traded for objects of similar significance.\n\nUsed at Renown Quartermasters and other vendors across Midnight zones." },
    [3317] = { name = "Визнання — Провалля 1-го сезону", en = "Renown - Season 1 Delves", desc = "[DNT]", den = "[DNT]" },
    [3318] = { name = "Подорож дослідника глибин", en = "Delver's Journey", desc = "Дає поступ у Подорожі дослідника глибин.", den = "Grants Delver's Journey progress." },
    [3319] = { name = "Відзнака Клинка Сутінків", en = "Twilight's Blade Insignia", desc = "Видається членам культу Клинка Сутінків під час їхньої ініціації. Торговці в Базовому таборі сходження в Сутінковому нагір'ї приймуть її як доказ ваших зусиль зірвати діяльність культистів.", den = "Given to members of the Twilight's Blade cult as part of their initiation. Vendors at the Ascension Basecamp in the Twilight Highlands will accept this as evidence of your efforts to thwart the cultist activity." },
    [3341] = { name = "Герб світанку ветерана", en = "Veteran Dawncrest", desc = "Використовується для покращення спорядження ветерана в 1-му сезоні Опівночі до рівня предметів 237-250.\n\nПри використанні в ремеслі задає рівень створеного предмета 233-246 залежно від якості.\n\nЗдобувається за такі дії:\n\n- Повторювані події у відкритому світі\n- Пошук рейду: Шпиль Порожнечі, Розлам Снів, Похід на Кел'Данас\n- Героїчні підземелля сезону\n- Провалля (рівні 5-6)\n- Винагорода шукача скарбів (рівні 4-5)\n- Полювання на здобич (важке)", den = "Used to upgrade Veteran equipment in Midnight Season 1 up to item levels 237-250.  \n\nWhen used for crafting, sets the item level of the resulting item to 233-246 based on Quality.\n\nEarned from the following activities:\n\n- Repeatable Outdoor Events\n- Raid Finder Voidspire, The Dreamrift, March On Quel'Danas\n- Heroic Season Dungeons\n- Delves (Tiers 5 to 6)\n- Trovehunter's Bounty (Tiers 4 to 5)\n- Prey Hunts (Hard)" },
    [3342] = { name = "Герб світанку ветерана", en = "Veteran Dawncrest", desc = "Використовується для покращення спорядження ветерана в 1-му сезоні Опівночі до рівня предметів 237-250. Здобувається за такі дії:\n\n- Повторювані події у відкритому світі\n- Пошук рейду: Шпиль Порожнечі, Розлам Снів, Похід на Кел'Данас\n- Героїчні підземелля сезону\n- Провалля (рівні 5-6)\n- Винагорода шукача скарбів (рівні 4-5)\n- Полювання на здобич (важке)", den = "Used to upgrade Veteran equipment in Midnight Season 1 up to item levels 237-250. Earned from the following activities:\n\n- Repeatable Outdoor Events\n- Raid Finder Voidspire, The Dreamrift, March On Quel'Danas\n- Heroic Season Dungeons\n- Delves (Tiers 5 to 6)\n- Trovehunter's Bounty (Tiers 4 to 5)\n- Prey Hunts (Hard)" },
    [3343] = { name = "Герб світанку чемпіона", en = "Champion Dawncrest", desc = "Використовується для покращення спорядження чемпіона в 1-му сезоні Опівночі до рівня предметів 250-263. Здобувається за такі дії:\n\n- Щотижневі події у відкритому світі\n- Звичайні: Шпиль Порожнечі, Розлам Снів, Похід на Кел'Данас\n- Міфічні підземелля сезону\n- Підземелля з міфічним ключем-каменем (+2 до +3)\n- Провалля (рівні 7-10)\n- Винагорода шукача скарбів (рівні 6-7)\n- Полювання на здобич (кошмарне)", den = "Used to upgrade Champion equipment in Midnight Season 1 up to item levels 250-263. Earned from the following activities:\n\n- Weekly Outdoor Events\n- Normal Voidspire, The Dreamrift, March On Quel'Danas\n- Mythic Season Dungeons\n- Mythic Keystone Dungeons (+2 to +3)\n- Delves (Tiers 7 to 10)\n- Trovehunter's Bounty (Tiers 6 to 7)\n- Prey Hunts (Nightmare)" },
    [3344] = { name = "Герб світанку чемпіона", en = "Champion Dawncrest", desc = "Використовується для покращення спорядження чемпіона в 1-му сезоні Опівночі до рівня предметів 250-263. Здобувається за такі дії:\n\n- Щотижневі події у відкритому світі\n- Звичайні: Шпиль Порожнечі, Розлам Снів, Похід на Кел'Данас\n- Міфічні підземелля сезону\n- Підземелля з міфічним ключем-каменем (+2 до +3)\n- Провалля (рівні 7-10)\n- Винагорода шукача скарбів (рівні 6-7)\n- Полювання на здобич (кошмарне)", den = "Used to upgrade Champion equipment in Midnight Season 1 up to item levels 250-263. Earned from the following activities:\n\n- Weekly Outdoor Events\n- Normal Voidspire, The Dreamrift, March On Quel'Danas\n- Mythic Season Dungeons\n- Mythic Keystone Dungeons (+2 to +3)\n- Delves (Tiers 7 to 10)\n- Trovehunter's Bounty (Tiers 6 to 7)\n- Prey Hunts (Nightmare)" },
    [3345] = { name = "Герб світанку героя", en = "Hero Dawncrest", desc = "Використовується для покращення спорядження героя в 1-му сезоні Опівночі до рівня предметів 263-276.\n\nПри використанні в ремеслі задає рівень створеного предмета 259-272 залежно від якості.\n\nЗдобувається за такі дії:\n\n- Героїчні: Шпиль Порожнечі, Розлам Снів, Похід на Кел'Данас\n- Підземелля з міфічним ключем-каменем (+4 до +8)\n- Провалля (рівень 11)\n- Винагорода шукача скарбів (рівень 8+)\n- Полювання на здобич (кошмарне)", den = "Used to upgrade Hero equipment in Midnight Season 1 up to item levels 263-276.  \n\nWhen used for crafting, sets the item level of the resulting item to 259-272 based on Quality.\n\nEarned from the following activities:\n\n- Heroic Voidspire, The Dreamrift, March On Quel'Danas\n- Mythic Keystone Dungeons (+4 to +8)\n- Delves (Tier 11)\n- Trovehunter's Bounty (Tier 8+)\n- Prey Hunts (Nightmare)" },
    [3346] = { name = "Герб світанку героя", en = "Hero Dawncrest", desc = "Використовується для покращення спорядження героя в 1-му сезоні Опівночі до рівня предметів 263-276. Здобувається за такі дії:\n\n- Героїчні: Шпиль Порожнечі, Розлам Снів, Похід на Кел'Данас\n- Підземелля з міфічним ключем-каменем (+4 до +8)\n- Провалля (рівень 11)\n- Винагорода шукача скарбів (рівень 8+)\n- Полювання на здобич (кошмарне)", den = "Used to upgrade Hero equipment in Midnight Season 1 up to item levels 263-276. Earned from the following activities:\n\n- Heroic Voidspire, The Dreamrift, March On Quel'Danas\n- Mythic Keystone Dungeons (+4 to +8)\n- Delves (Tier 11)\n- Trovehunter's Bounty (Tier 8+)\n- Prey Hunts (Nightmare)" },
    [3347] = { name = "Герб світанку міфу", en = "Myth Dawncrest", desc = "Використовується для покращення міфічного спорядження в 1-му сезоні Опівночі до рівня предметів 276-289.\n\nПри використанні в ремеслі задає рівень створеного предмета 272-285 залежно від якості.\n\nЗдобувається за такі дії:\n\n- Міфічні: Шпиль Порожнечі, Розлам Снів, Похід на Кел'Данас\n- Підземелля з міфічним ключем-каменем (+9 і вище)", den = "Used to upgrade Myth equipment in Midnight Season 1 up to item levels 276-289.  \n\nWhen used for crafting, sets the item level of the resulting item to 272-285 based on Quality.\n\nEarned from the following activities:\n\n- Mythic Voidspire, The Dreamrift, March On Quel'Danas\n- Mythic Keystone Dungeons (+9 and up)" },
    [3348] = { name = "Герб світанку міфу", en = "Myth Dawncrest", desc = "Використовується для покращення міфічного спорядження в 1-му сезоні Опівночі до рівня предметів 276-289. Здобувається за такі дії:\n\n- Героїчні: Шпиль Порожнечі, Розлам Снів, Похід на Кел'Данас\n- Підземелля з міфічним ключем-каменем (+9 і вище)", den = "Used to upgrade Myth equipment in Midnight Season 1 up to item levels 276-289. Earned from the following activities:\n\n- Heroic Voidspire, The Dreamrift, March On Quel'Danas\n- Mythic Keystone Dungeons (+9 and up)" },
