    [3354] = { name = "Плем'я Амані", en = "The Amani Tribe", desc = "Дає репутацію з племенем Амані.", den = "Grants Reputation with the Amani Tribe." },
    [3355] = { name = "Визнання — Плем'я Амані", en = "Renown - The Amani Tribe", desc = "[DNT]", den = "[DNT]" },
    [3356] = { name = "Незаплямовані кристали мани", en = "Untainted Mana-Crystals", desc = "Можна здобути після досягнення 9-го рангу Подорожі дослідника глибин. Можна отримати з відкриття щедрих скринь відновленими ключами від скринь у щедрих проваллях 11-го рівня. Можна обміняти в Зах'рана на потужне спорядження.", den = "Can be earned after reaching rank 9 of the Delver's Journey. May be obtained from opening Bountiful Coffers with Restored Coffer Keys inside of bountiful delves at Tier 11. Can be traded with Zah'ran for powerful equipment." },
    [3360] = { name = "[DNT] 11.1.5 Середина сезону — Лічильник здачі завдань Турбопідсилення", en = "[DNT] 11.1.5 Midseason - Turbo-Boost Quest Turn-In Tracker" },
    [3363] = { name = "Громадські купони", en = "Community Coupons", desc = "Здобуваються за виконання завдань ініціатив на підтримку вашого району та його друзів. Використовуються для придбання предметів у торговців ініціатив.", den = "Earned from completing Endeavor tasks to support your Neighborhood and its friends. Used to purchase items from Endeavor Traders." },
    [3364] = { name = "[DNT] 11.2.5 Середина сезону — Лічильник здачі завдань Турбопідсилення", en = "[DNT] 11.2.5 Midseason - Turbo-Boost Quest Turn-In Tracker" },
    [3365] = { name = "Двір Сільвермуна", en = "Silvermoon Court", desc = "Дає репутацію з Двором Сільвермуна.", den = "Grants Reputation with the Silvermoon Court." },
    [3369] = { name = "Визнання — Хара'ті", en = "Renown - The Hara'ti", desc = "[DNT]", den = "[DNT]" },
    [3370] = { name = "Хара'ті", en = "The Hara'ti", desc = "Дає репутацію з Хара'ті.", den = "Grants Reputation with the Hara'ti." },
    [3371] = { name = "Визнання — Двір Сільвермуна", en = "Renown - Silvermoon Court", desc = "[DNT]", den = "[DNT]" },
    [3372] = { name = "Бронза", en = "Bronze", desc = "Часточка часу, спресована в бронзову монету. Нескінченний драконовий рій обміняє її на оздоблювальні нагороди.", den = "A mote of time compressed into a bronze coin. The infinite dragonflight will trade this for cosmetic rewards." },
    [3373] = { name = "Перли рибалки", en = "Angler Pearls", desc = "Здебільшого трапляються в Глибинах Зул'Амана й використовуються виключно для торгівлі з глибоководцем Джеджу та глибоководцем Ту'накітом.", den = "Primarily found in the Zul'Aman Depths and used exclusively in trade with Depthdiver Jeju and Depthdiver Tu'nakit." },
    [3375] = { name = "[DNT] Валюта відстеження Полювання на молей", en = "[DNT] Moth Hunt Tracking Currency" },
    [3376] = { name = "Скалка Дундуна", en = "Shard of Dundun", desc = "Піднесіть у місці рясності, щоб після жнив отримати винагороду — чисту рясність.", den = "Offer at an Abundant location to be rewarded with Unalloyed Abundance after the harvest." },
    [3377] = { name = "Чистий достаток", en = "Unalloyed Abundance", desc = "Чиста щедрість землі, пробуджена Лоа достатку та зібрана під час щедрих жнив. Використовується для придбання товарів у Чела Кербиша.", den = "Pure bounty of the land, stirred by the Loa of Abundance and claimed through Abundant Harvests. Used to purchase goods from Chel the Chip." },
    [3378] = { name = "Маноплин світанку", en = "Dawnlight Manaflux", desc = "Маноплин світанку заряджає Каталізатор і дає йому змогу наділяти обладунки неймовірною силою. Повільно накопичується кожні два тижні.", den = "Dawnlight Manaflux charges the Catalyst and allows it to imbue armor with incredible power. Slowly accumulates every two weeks." },
    [3379] = { name = "Переповнена аркана", en = "Brimming Arcana", desc = "Цим можуть зацікавитися торговці в Притулку Салтеріла.", den = "Vendors at Saltheril's Haven might be interested in this." },
    [3383] = { name = "Світанковий герб шукача пригод", en = "Adventurer Dawncrest", desc = "Використовується для покращення спорядження шукача пригод у 1-му сезоні Опівночі до рівнів предметів 224-237.\n\nПри використанні у виготовленні задає рівень створеного предмета 220-233 залежно від якості.\n\nОтримується за такі дії:\n\n- Повторювані події під відкритим небом\n- Прірви 4-го рівня\n- Полювання на здобич (звичайне)", den = "Used to upgrade Adventurer equipment in Midnight Season 1 up to item levels 224-237. \n\nWhen used for crafting, sets the item level of the resulting item to 220-233 based on Quality.\n\nEarned from the following activities:\n\n- Repeatable Outdoor Events\n- Tier 4 Delves\n- Prey Hunts (Normal)" },
    [3385] = { name = "Осяйний пил", en = "Luminous Dust", desc = "Тонкий пил, зібраний з молей, що водяться лише в Гарандарі. Його можна обміняти в Доглядачки молей Вев'там.", den = "A fine dust collected from moths found only in Harandar. This can be traded to Mothkeeper Wew'tam." },
