    [3391] = { name = "Світанковий герб шукача пригод", en = "Adventurer Dawncrest", desc = "Використовується для покращення спорядження шукача пригод у 1-му сезоні Опівночі до рівнів предметів 224-237. Отримується за такі дії:\n\n- Повторювані події під відкритим небом\n- Прірви 4-го рівня\n- Полювання на здобич (звичайне)", den = "Used to upgrade Adventurer equipment in Midnight Season 1 up to item levels 224-237. Earned from the following activities:\n\n- Repeatable Outdoor Events\n- Tier 4 Delves\n- Prey Hunts (Normal)" },
    [3392] = { name = "Залишок муки", en = "Remnant of Anguish", desc = "Вирує далекими криками болю.\n\nЦим зацікавився б Конструкт В'аноре в Святилищі Асталора у Сільвермуні.", den = "Seethes with distant screams of pain.\n\nConstruct V'anore at Astalor's Sanctum in Silvermoon would be interested in this." },
    [3393] = { name = "Ілюзорна монета", en = "Illusionary Coin", desc = "Чаклунська валюта, якою користуються деякі мешканці Сільвермуна, що полюбляють магічні ігри.", den = "An arcane currency used by some denizens of Silvermoon fond of magical games." },
