    [3400] = { name = "Незабруднений зразок Порожнечі", en = "Uncontaminated Void Sample", desc = "Зразки, які можна використати для подальших досліджень Порожнечі. Їх можна застосувати на консолі досліджень на Виючому хребті в Бурі Порожнечі.", den = "Samples that can be used to further research into the void. These can be used at the Research console at the Howling Ridge in the Voidstorm." },
