    [3405] = { name = "Польова відзнака", en = "Field Accolade", desc = "Марен Срібнокрила обміняє їх на схованки, торкнуті Порожнечею, у Сільвермуні.", den = "Maren Silverwing will exchange these for Void-Touched Caches in Silvermoon City." },
