    [3418] = { name = "Туманне ядро Порожнечі", en = "Nebulous Voidcore", desc = "Перетворюється на потужне спорядження після перемоги над могутніми ворогами в рейдах 1-го сезону Опівночі або проходження підземель у режимі Міфік+, щедрих прірв і полювань на здобич на складності «Жахіття».", den = "Transmutable into powerful equipment upon defeating powerful foes in Midnight Season 1 raids or completing Mythic+ dungeons, Bountiful Delves and Prey Hunts on Nightmare difficulty." },
